/**
 * Fail-soft, cached runtime loader for the two generated, checked-in JSON
 * files that drive the Jev router (docs/designs/2026-09-22-jev-caroline-router.md
 * §A): `caroline-questions.json` (the exact Jev `questions` object) and
 * `caroline-inventory.json` (tool/skill/intent metadata, used only for the
 * `intent -> action_type_on_handoff` mapping on escalation).
 *
 * Both files are owned and generated by scripts/gen-caroline-inventory.sh
 * (a separate workstream) and are read here by PATH, never imported — this
 * repo's tsconfig.json has no `resolveJsonModule` and excludes non-.ts files
 * from `include`, so `tsc` never copies them into dist/, and a static
 * `import ... from "./caroline-questions.json"` would not compile.
 *
 * ASSUMPTION (flagged, not verified against the deploy pipeline): at deploy
 * time it is unclear whether dist/ ships alongside a copy of these JSON
 * files or whether only src/ does. We try both the compiled module's own
 * directory (works if a future build step copies the JSON into dist/) and
 * the sibling src/ directory (works if the deploy ships the source tree
 * alongside dist/, as most of this repo's rsync targets do), so this loader
 * keeps working under either outcome. On this branch neither file exists yet
 * (owned by a concurrent, in-flight change) — every call below fails soft to
 * `null`/`[]` and logs one warn per process lifetime.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const THIS_DIR = dirname(fileURLToPath(import.meta.url));
const CANDIDATE_DIRS = [THIS_DIR, join(THIS_DIR, "..", "src")];

function readJson(filename: string): unknown | null {
  for (const dir of CANDIDATE_DIRS) {
    try {
      const raw = readFileSync(join(dir, filename), "utf8");
      return JSON.parse(raw);
    } catch {
      // try the next candidate directory
    }
  }
  return null;
}

// The exact Jev `questions` object — see caroline-questions.json's shape in
// the design doc §A. Left as `Record<string, unknown>` here: the plugin
// treats it as an opaque payload it forwards to callJev unmodified.
export type CarolineQuestions = Record<string, unknown>;

export interface CarolineIntentMeta {
  intent: string;
  description?: string;
  first_read_tool?: string;
  write_tools?: string[];
  handoff_when?: string;
  action_type_on_handoff?: string;
}

export interface CarolineSkillMeta {
  name: string;
  activates_when?: string;
  tools_used?: string[];
  outcome?: string;
}

// v2-only. caroline-tool-capabilities.json: per-tool declared answer/cannot
// capabilities plus the human_gated / kb_topics policy — see
// caroline-tool-capabilities.json's own top-level comment for provenance.
export interface CarolineToolCapability {
  name: string;
  answers: string[];
  cannot_answer: string[];
  needs: string;
}

export interface CarolineCapabilitiesPolicy {
  human_gated: string[];
  kb_topics: string[];
}

export interface CarolineCapabilities {
  tools: CarolineToolCapability[];
  policy: CarolineCapabilitiesPolicy;
}

let cachedQuestionsV2: CarolineQuestions | null | undefined;
let warnedQuestionsV2 = false;

let cachedQuestions: CarolineQuestions | null | undefined;
let cachedIntents: CarolineIntentMeta[] | null | undefined;
let cachedSkills: CarolineSkillMeta[] | null | undefined;
let cachedCapabilities: CarolineCapabilities | null | undefined;
let warnedQuestions = false;
let warnedIntents = false;
let warnedSkills = false;
let warnedCapabilities = false;

export function loadCarolineQuestions(log?: { warn: (msg: string) => void }): CarolineQuestions | null {
  if (cachedQuestions !== undefined) return cachedQuestions;
  const data = readJson("caroline-questions.json");
  cachedQuestions = (data as CarolineQuestions | null) ?? null;
  if (cachedQuestions === null && !warnedQuestions) {
    warnedQuestions = true;
    log?.warn("[intercom:jev] caroline-questions.json not found — jev routing disabled for this process");
  }
  return cachedQuestions;
}

export function loadCarolineQuestionsV2(log?: { warn: (msg: string) => void }): CarolineQuestions | null {
  if (cachedQuestionsV2 !== undefined) return cachedQuestionsV2;
  const data = readJson("caroline-questions.v2.json");
  cachedQuestionsV2 = (data as CarolineQuestions | null) ?? null;
  if (cachedQuestionsV2 === null && !warnedQuestionsV2) {
    warnedQuestionsV2 = true;
    log?.warn("[intercom:jev] caroline-questions.v2.json not found — jev v2 routing disabled for this process");
  }
  return cachedQuestionsV2;
}

export function loadCarolineIntents(log?: { warn: (msg: string) => void }): CarolineIntentMeta[] {
  if (cachedIntents !== undefined) return cachedIntents ?? [];
  const data = readJson("caroline-inventory.json") as { intents?: CarolineIntentMeta[] } | null;
  cachedIntents = data?.intents ?? null;
  if (cachedIntents === null && !warnedIntents) {
    warnedIntents = true;
    log?.warn("[intercom:jev] caroline-inventory.json not found — action_type_on_handoff mapping unavailable");
  }
  return cachedIntents ?? [];
}

export function loadCarolineSkills(log?: { warn: (msg: string) => void }): CarolineSkillMeta[] {
  if (cachedSkills !== undefined) return cachedSkills ?? [];
  const data = readJson("caroline-inventory.json") as { skills?: CarolineSkillMeta[] } | null;
  cachedSkills = data?.skills ?? null;
  if (cachedSkills === null && !warnedSkills) {
    warnedSkills = true;
    log?.warn("[intercom:jev] caroline-inventory.json not found — intent-to-skill table mapping unavailable");
  }
  return cachedSkills ?? [];
}

export function loadCarolineToolCapabilities(log?: { warn: (msg: string) => void }): CarolineCapabilities | null {
  if (cachedCapabilities !== undefined) return cachedCapabilities;
  const data = readJson("caroline-tool-capabilities.json") as
    | { tools?: CarolineToolCapability[]; policy?: CarolineCapabilitiesPolicy }
    | null;
  cachedCapabilities =
    data?.tools && data.policy ? { tools: data.tools, policy: data.policy } : null;
  if (cachedCapabilities === null && !warnedCapabilities) {
    warnedCapabilities = true;
    log?.warn("[intercom:jev] caroline-tool-capabilities.json not found — v2 tools/policy unavailable");
  }
  return cachedCapabilities;
}

// Test-only: each test file wants a clean cache/warn-once state.
export function __resetCarolineInventoryCacheForTests(): void {
  cachedQuestions = undefined;
  cachedQuestionsV2 = undefined;
  cachedIntents = undefined;
  cachedSkills = undefined;
  cachedCapabilities = undefined;
  warnedQuestions = false;
  warnedQuestionsV2 = false;
  warnedIntents = false;
  warnedSkills = false;
  warnedCapabilities = false;
}
